package com.citacloud.app.models;
import jakarta.persistence.*; import java.util.UUID;
@Entity @Table(name="configuracion_empresa_fase2") public class ConfiguracionEmpresaFase2 { @Id @Column(name="empresa_id") private UUID empresaId; @Column(name="requiere_aprobacion_citas") private boolean requiereAprobacionCitas; @Column(name="prefijo_factura") private String prefijoFactura="FAC"; @Column(name="siguiente_factura") private int siguienteFactura=1; @Column(name="recordatorios_activos") private boolean recordatoriosActivos=true; public UUID getEmpresaId(){return empresaId;} public void setEmpresaId(UUID v){empresaId=v;} public boolean isRequiereAprobacionCitas(){return requiereAprobacionCitas;} public void setRequiereAprobacionCitas(boolean v){requiereAprobacionCitas=v;} public String getPrefijoFactura(){return prefijoFactura;} public void setPrefijoFactura(String v){prefijoFactura=v;} public int getSiguienteFactura(){return siguienteFactura;} public void setSiguienteFactura(int v){siguienteFactura=v;} public boolean isRecordatoriosActivos(){return recordatoriosActivos;} public void setRecordatoriosActivos(boolean v){recordatoriosActivos=v;} }
